ALTER TABLE "turnstile"."configuration_audit" DROP CONSTRAINT "audit_fields";--> statement-breakpoint
ALTER TABLE "turnstile"."configuration_audit" ADD COLUMN "subject_user_id" text;--> statement-breakpoint
ALTER TABLE "turnstile"."configuration_audit" ADD CONSTRAINT "audit_subject_user" CHECK (("turnstile"."configuration_audit"."action" = 'access_changed' AND "turnstile"."configuration_audit"."actor_kind" = 'operator' AND "turnstile"."configuration_audit"."subject_user_id" IS NOT NULL AND "turnstile"."configuration_audit"."subject_user_id" ~ '^[A-Za-z0-9_-]{1,200}$') OR ("turnstile"."configuration_audit"."action" <> 'access_changed' AND "turnstile"."configuration_audit"."subject_user_id" IS NULL));--> statement-breakpoint
ALTER TABLE "turnstile"."configuration_audit" ADD CONSTRAINT "audit_fields" CHECK (cardinality("turnstile"."configuration_audit"."changed_fields") <= 6 AND "turnstile"."configuration_audit"."changed_fields" <@ ARRAY['name','timeZone','type','parentId','completion','permissions','enabled']::text[]);